vector<int> parseRow(const string& s) {
    vector<int> v; long long x=0; int sign=1; bool in=false;
    for(char ch: s){
        if(ch=='-'){ sign=-1; }
        else if(isdigit((unsigned char)ch)){ x=x*10+(ch-'0'); in=true; }
        else if(in){ v.push_back((int)(sign*x)); x=0; sign=1; in=false; }
    }
    if(in) v.push_back((int)(sign*x));
    return v;
}
vector<vector<int>> parseMatrix(const string& s) {
    vector<vector<int>> m; int depth=0, start=-1;
    for(int i=0;i<(int)s.size();++i){
        if(s[i]=='['){
            ++depth;
            if(depth==3) start=i;
        } else if(s[i]==']'){
            if(depth==3 && start!=-1){ m.push_back(parseRow(s.substr(start, i-start+1))); start=-1; }
            --depth;
        }
    }
    return m;
}
