    cout << '[';
    for(int i=0;i<(int)a.size();++i){ if(i) cout << ','; cout << '['; for(int j=0;j<(int)a[i].size();++j){ if(j) cout << ','; cout << a[i][j]; } cout << ']'; }
    cout << "]\n";
}
