        while (i < n && s.charAt(i) != '[') i++;
        // outer argument array
        i++;
        while (i < n && s.charAt(i) != '[') i++;
        List<int[]> rows = new ArrayList<>();
        while (i < n && s.charAt(i) == '[') {
            i++;
            ArrayList<Integer> vals = new ArrayList<>();
            StringBuilder num = new StringBuilder();
            while (i < n && s.charAt(i) != ']') {
                char ch = s.charAt(i);
                if (ch == '-' || Character.isDigit(ch)) num.append(ch);
                else if (ch == ',' && num.length() > 0) { vals.add(Integer.parseInt(num.toString())); num.setLength(0); }
                i++;
            }
            if (num.length() > 0) vals.add(Integer.parseInt(num.toString()));
            i++;
            int[] row = new int[vals.size()];
            for (int k=0;k<vals.size();k++) row[k]=vals.get(k);
            rows.add(row);
            while (i<n && (s.charAt(i)==',' || Character.isWhitespace(s.charAt(i)))) i++;
        }
        return rows.toArray(new int[0][]);
    }
